CREATE TABLE Users (
    user_id INT PRIMARY KEY,              -- Entity Integrity
    email VARCHAR(255) UNIQUE NOT NULL,   -- Key & Domain Constraint
    age INT CHECK (age >= 18)             -- Domain Constraint
);

CREATE TABLE Orders (
    order_id INT PRIMARY KEY,
    user_id INT REFERENCES Users(user_id) -- Referential Integrity
    ON DELETE CASCADE
);

