);

interview_questions.answer:
WITH CTE AS (
    SELECT id, ROW_NUMBER() OVER (PARTITION BY email ORDER BY id ASC) as rn
    FROM Users
)
DELETE FROM Users WHERE id IN (SELECT id FROM CTE WHERE rn > 1);

