-- Correlated Subquery Example:
SELECT e.name, e.salary, e.dept_id
FROM Employees e
WHERE e.salary > (
    SELECT AVG(salary) 
    FROM Employees 
    WHERE dept_id = e.dept_id -- References outer query e.dept_id!
);

-- EXISTS Short-circuit Check:
SELECT c.name FROM Customers c
WHERE EXISTS (
    SELECT 1 FROM Orders o WHERE o.cust_id = c.id
);

-- Pessimistic Locking (Prevents Double Spend):
BEGIN;
SELECT balance FROM Accounts WHERE account_id = 101 FOR UPDATE; -- Acquires X-Lock!
UPDATE Accounts SET balance = balance - 100 WHERE account_id = 101;
COMMIT;

-- Optimistic Locking (Prevents Double Booking):
UPDATE Products 
SET stock = stock - 1, version = version + 1 
WHERE id = 500 AND version = 12; -- If version changed, 0 rows updated!

-- WRONG (Index Ignored -> Full Table Scan):
SELECT * FROM Users WHERE LOWER(email) = 'alice@gmail.com';
SELECT * FROM Orders WHERE order_date + INTERVAL '1 day' = '2026-01-01';
SELECT * FROM Users WHERE phone = 9876543210; -- phone is VARCHAR!

-- RIGHT (Index Used -> Fast B+ Tree Lookup):
SELECT * FROM Users WHERE email = 'alice@gmail.com';
SELECT * FROM Orders WHERE order_date = '2026-01-01' - INTERVAL '1 day';
SELECT * FROM Users WHERE phone = '9876543210';
